create table if not exists public.inquiries (id uuid primary key default gen_random_uuid(), lead_code text unique, full_name text not null, contact text, interest text, follow_up_date date, status text not null default 'New', notes text, assigned_to uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.bookings (id uuid primary key default gen_random_uuid(), booking_code text unique, customer_id uuid references public.customers(id) on delete set null, customer_name text not null, service_type text not null, travel_date date, amount numeric(12,2) not null default 0 check(amount>=0), currency text not null default 'PKR', status text not null default 'Pending', notes text, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['inquiries','bookings'] LOOP EXECUTE format('alter table public.%I enable row level security',t); EXECUTE format('drop policy if exists %I on public.%I',t||'_staff_read',t); EXECUTE format('create policy %I on public.%I for select to authenticated using (public.is_crm_staff())',t||'_staff_read',t); EXECUTE format('drop policy if exists %I on public.%I',t||'_staff_write',t); EXECUTE format('create policy %I on public.%I for all to authenticated using (public.is_crm_staff() and public.current_user_role() in (''admin'',''manager'',''agent'')) with check (public.is_crm_staff() and public.current_user_role() in (''admin'',''manager'',''agent''))',t||'_staff_write',t); END LOOP; END $$;
